    return ("wh", start, end, now)

if name == "lh":
    # 多维限流历史：精确键序 op,scope,id,from,to,now（键须按此序出现），
    # 只读；scope 仅 B/C/S，id 沿用 ls 的非空 UTF-8 串校验（未知 B id、
    # 无桶无配额与 from 过早留执行期判）。数值与窗关系约束同 oh。
